import com.noteforge.platform.mapper.LinkPreviewMapper;
import com.noteforge.platform.mapper.ResourceMapper;
import com.noteforge.platform.service.LinkPreviewService;
import com.noteforge.platform.service.ResourceService;
import com.sun.net.httpserver.HttpExchange;
import com.sun.net.httpserver.HttpServer;

import java.io.OutputStream;
import java.lang.reflect.Field;
import java.net.InetSocketAddress;
import java.net.ServerSocket;
import java.nio.charset.StandardCharsets;
import java.util.List;
import java.util.concurrent.Executors;

public class TestServices {

    static int failures = 0;
    static int checks = 0;

    static void check(boolean cond, String label) {
        checks++;
        if (!cond) {
            failures++;
            System.out.println("FAIL: " + label);
        }
    }

    static class FakeLinkPreviewMapper implements LinkPreviewMapper {
        long seq = 0;
        LinkPreview last;
        public void insert(LinkPreview p) { p.setId(++seq); last = p; }
        public LinkPreview findById(Long id) { return null; }
        public List<LinkPreview> findByOwnerId(Long ownerId) { return List.of(); }
    }

    static class FakeResourceMapper implements ResourceMapper {
        long seq = 0;
        Resource last;
        List<Resource> listResult = List.of();
        public void insert(Resource r) { r.setId(++seq); last = r; }
        public Resource findById(Long id) { return null; }
        public List<Resource> findByOwnerId(Long ownerId) { return listResult; }
    }

    static void inject(Object target, String field, Object value) throws Exception {
        Field f = target.getClass().getDeclaredField(field);
        f.setAccessible(true);
        f.set(target, value);
    }

    static LinkPreviewRequest lpReq(String url) {
        LinkPreviewRequest r = new LinkPreviewRequest();
        r.setUrl(url);
        return r;
    }

    static ResourceFetchRequest rfReq(String url, Long noteId) {
        ResourceFetchRequest r = new ResourceFetchRequest();
        r.setUrl(url);
        r.setNoteId(noteId);
        return r;
    }

    static void respond(HttpExchange ex, int code, String contentType, byte[] body, boolean chunked) throws Exception {
        if (contentType != null) ex.getResponseHeaders().set("Content-Type", contentType);
        if (chunked) {
            ex.sendResponseHeaders(code, 0);
        } else {
            ex.sendResponseHeaders(code, body.length == 0 ? -1 : body.length);
        }
        if (body.length > 0) {
            try (OutputStream os = ex.getResponseBody()) { os.write(body); }
        } else {
            ex.close();
        }
    }

    public static void main(String[] args) throws Exception {
        int port = 18099;
        HttpServer server = HttpServer.create(new InetSocketAddress("127.0.0.1", port), 0);
        server.setExecutor(Executors.newFixedThreadPool(8));

        String page = "<html><head>\n"
                + "  <title>  Test   Page  </title>\n"
                + "  <meta name=\"description\" content=\"A test description\">\n"
                + "  <link rel=\"shortcut icon\" href=\"/favicon.ico\">\n"
                + "</head><body>hello</body></html>";
        server.createContext("/page.html", ex -> respond(ex, 200, "text/html; charset=utf-8",
                page.getBytes(StandardCharsets.UTF_8), false));

        String rev = "<HTML><HEAD>"
                + "<TITLE>Upper Title</TITLE>"
                + "<meta content='Reversed description' name='DESCRIPTION'>"
                + "<link href=\"http://example.com/fav.png\" rel=icon type='image/png'>"
                + "</HEAD><BODY></BODY></HTML>";
        server.createContext("/rev.html", ex -> respond(ex, 200, "text/html",
                rev.getBytes(StandardCharsets.UTF_8), false));

        String bare = "<html><body>no head metadata here</body></html>";
        server.createContext("/bare.html", ex -> respond(ex, 200, "text/html",
                bare.getBytes(StandardCharsets.UTF_8), false));

        server.createContext("/plain.txt", ex -> respond(ex, 200, "text/plain",
                "just some text".getBytes(StandardCharsets.UTF_8), false));

        server.createContext("/notfound", ex -> respond(ex, 404, "text/html",
                "<html><head><title>404</title></head></html>".getBytes(StandardCharsets.UTF_8), false));

        server.createContext("/chunked", ex -> respond(ex, 200, "text/html",
                "<html><head><title>Chunked</title></head></html>".getBytes(StandardCharsets.UTF_8), true));

        server.createContext("/slow", ex -> {
            try {
                Thread.sleep(12000);
                respond(ex, 200, "text/html", "late".getBytes(StandardCharsets.UTF_8), false);
            } catch (Exception ignored) { }
        });

        server.start();

        int deadPort;
        try (ServerSocket ss = new ServerSocket(0)) { deadPort = ss.getLocalPort(); }

        LinkPreviewService lp = new LinkPreviewService();
        FakeLinkPreviewMapper flp = new FakeLinkPreviewMapper();
        inject(lp, "linkPreviewMapper", flp);

        ResourceService rs = new ResourceService();
        FakeResourceMapper frm = new FakeResourceMapper();
        inject(rs, "resourceMapper", frm);

        String base = "http://127.0.0.1:" + port;
        String dead = "http://127.0.0.1:" + deadPort;

        // ---- LinkPreviewService (a): invalid / null URL ----
        ApiResponse<?> r = lp.generatePreview(lpReq("ftp://example.com/x"), 42L);
        check(r.getCode() == 400, "lp invalid code");
        check("URL必须以http://或https://开头".equals(r.getMessage()), "lp invalid message: " + r.getMessage());
        check(r.getData() == null, "lp invalid data null");
        check(flp.last == null, "lp invalid no row");

        r = lp.generatePreview(lpReq(null), 42L);
        check(r.getCode() == 400 && r.getData() == null && flp.last == null, "lp null url");

        r = lp.generatePreview(lpReq("javascript:alert(1)"), 42L);
        check(r.getCode() == 400 && flp.last == null, "lp js url");

        // ---- LinkPreviewService (b): valid pages ----
        r = lp.generatePreview(lpReq(base + "/page.html"), 42L);
        check(r.getCode() == 200, "lp page code");
        check("预览生成成功".equals(r.getMessage()), "lp page message: " + r.getMessage());
        LinkPreview p = (LinkPreview) r.getData();
        check(p != null && p.getId() != null && p.getId() == 1L, "lp page id generated");
        check("Test   Page".equals(p.getTitle()), "lp page title: '" + p.getTitle() + "'");
        check("A test description".equals(p.getDescription()), "lp page description: " + p.getDescription());
        check("/favicon.ico".equals(p.getFaviconUrl()), "lp page favicon: " + p.getFaviconUrl());
        check(p.getOwnerId() != null && p.getOwnerId() == 42L, "lp page ownerId");
        check(p.getUrl() != null && p.getUrl().equals(base + "/page.html"), "lp page url stored");
        check(p.getCreatedAt() != null, "lp page createdAt");
        check(flp.last == p, "lp page row");

        r = lp.generatePreview(lpReq(base + "/rev.html"), 42L);
        p = (LinkPreview) r.getData();
        check("预览生成成功".equals(r.getMessage()), "lp rev message");
        check("Upper Title".equals(p.getTitle()), "lp rev title: " + p.getTitle());
        check("Reversed description".equals(p.getDescription()), "lp rev description: " + p.getDescription());
        check("http://example.com/fav.png".equals(p.getFaviconUrl()), "lp rev favicon: " + p.getFaviconUrl());

        r = lp.generatePreview(lpReq(base + "/bare.html"), 42L);
        p = (LinkPreview) r.getData();
        check("预览生成成功".equals(r.getMessage()), "lp bare message");
        check(p.getTitle() == null && p.getDescription() == null && p.getFaviconUrl() == null, "lp bare null metadata");
        check(p.getId() != null, "lp bare id");

        r = lp.generatePreview(lpReq(base + "/plain.txt"), 42L);
        p = (LinkPreview) r.getData();
        check("预览生成成功".equals(r.getMessage()), "lp plain message");
        check(p.getTitle() == null, "lp plain title null");

